package com.floratend.app

import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.runBlocking
import org.junit.Rule
import org.junit.Test
import org.junit.Assert.*
import java.time.LocalDate

/** Real optimized nondebug app/Room/UI workflow; no billing fixture or entitlement mutation. */
class MinifiedCareWorkflowTest {
    @get:Rule val rule=createAndroidComposeRule<MainActivity>()
    @Test fun filtersAndAllCareActionsRemainUsableAfterColdEntry()=runBlocking {
        check(BuildConfig.APPLICATION_ID.endsWith(".perf") && !BuildConfig.DEBUG)
        val app=rule.activity.application as FloraApp
        val plants=app.database.dao().plants().first()
        check(plants.size==120 && plants.all { it.id.startsWith("qa-large-photo-") })
        val plant=plants.single { it.name=="Photo fern 000" }
        val original=app.database.dao().schedules().first().single { it.plantId==plant.id }
        val locale=AppLocales.selected(app)
        try {
            AppLocales.choose(app,"en-GB");rule.activityRule.scenario.recreate()
            rule.onNodeWithText("Calendar",substring=false).performScrollTo().performClick()
            rule.onNodeWithText(rule.activity.getString(R.string.month),substring=false).performClick()
            rule.onNode(hasText(plant.name,substring=false) and hasClickAction()).performClick()
            rule.onNodeWithText("Pause",substring=false).performScrollTo().performClick()
            rule.waitUntil(10000) { rule.onAllNodesWithText("Resume",substring=false).fetchSemanticsNodes().isNotEmpty() }
            rule.onNodeWithText("Record care",substring=false).assertIsNotEnabled()
            rule.onNodeWithText("Resume",substring=false).performClick()
            rule.waitUntil(10000) { rule.onAllNodesWithText("Pause",substring=false).fetchSemanticsNodes().isNotEmpty() }
            rule.onNodeWithText("Record care",substring=false).assertIsEnabled()
            rule.onNodeWithText("Snooze until tomorrow",substring=false).performClick()
            rule.waitUntil(10000) { runBlocking { app.database.dao().schedules().first().single {it.id==original.id}.nextDate==LocalDate.now().plusDays(1).toString() } }
            rule.onNodeWithText("Reschedule",substring=false).performClick()
            rule.onNodeWithText("Date (YYYY-MM-DD)",substring=false).performTextReplacement(original.nextDate)
            rule.onNodeWithText("Save",substring=false).performClick()
            rule.waitUntil(10000) { runBlocking { app.database.dao().schedules().first().single {it.id==original.id}.nextDate==original.nextDate } }
            rule.onNodeWithText("Record care",substring=false).performClick()
            rule.onNodeWithText(rule.activity.getString(R.string.cancel),substring=false).performClick()
            assertEquals(120,app.database.dao().history().first().size)
            rule.activityRule.scenario.recreate()
            assertEquals(original.nextDate,app.database.dao().schedules().first().single {it.id==original.id}.nextDate)
        } finally { app.database.dao().save(original);AppLocales.choose(app,locale) }
    }
}
